use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i128),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store.
/// Variables not present in the store evaluate to -1.
pub fn eval(e: &Exp, store: &HashMap<String, i128>) -> i128 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(a, b) => eval(a, store) + eval(b, store),
        Exp::Mult(a, b) => eval(a, store) * eval(b, store),
    }
}

/// Perform a single-step peephole optimization at the root only.
/// Does not recurse into sub-expressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(a, b) => {
            match (&*a, &*b) {
                // absorbing element: 0 * x = 0, x * 0 = 0
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

                // neutral element: 1 * x = x, x * 1 = x
                (Exp::Const(1), _) => (*b).clone(),
                (_, Exp::Const(1)) => (*a).clone(),

                // constant folding
                (Exp::Const(x), Exp::Const(y)) => Exp::Const(*x * *y),

                // no rule applies
                _ => Exp::Mult(a, b),
            }
        }
        Exp::Plus(a, b) => {
            match (&*a, &*b) {
                // neutral element: 0 + x = x, x + 0 = x
                (Exp::Const(0), _) => (*b).clone(),
                (_, Exp::Const(0)) => (*a).clone(),

                // constant folding
                (Exp::Const(x), Exp::Const(y)) => Exp::Const(*x + *y),

                // no rule applies
                _ => Exp::Plus(a, b),
            }
        }
        other => other,
    }
}

/// Check (by computation) that optimization preserves evaluation for this `e` and `s`.
/// (In a proof assistant this would be a theorem; in Rust we can only compute/compare.)
pub fn optimize_correct(e: Exp, s: &HashMap<String, i128>) -> bool {
    let v1 = eval(&e, s);
    let v2 = eval(&optimize(e), s);
    v1 == v2
}

